// Framework-independent rendering engine. No global selectors or persistent listeners.
const ASSETS = {"olivia": "data:image/png;base64,", "daniel": "data:image/png;base64,", "marcus": "data:image/png;base64,", "sophia": "data:image/png;base64,"};
const stages = [
 ['Discover','Find your next great conversation.','Bring prospects from multiple sources into one enriched profile.','Four signals. One promising prospect.'],
 ['Research','Turn public signals into context.','Understand the company, the timing, and the opportunity.','Research signals are paired with illustrative source labels.'],
 ['Qualify','Focus on the right fit.','Check every prospect against your ideal customer profile.','A clear match moves forward. Everyone else stays out.'],
 ['Personalize','Make every word relevant.','Connect verified context to a message that feels human.','Each highlighted phrase traces back to a specific signal.'],
 ['Outreach','From thoughtful draft to delivery.','Move qualified prospects through a focused outbound queue.','A personalized message, sent with intention.'],
 ['Converse','Turn a reply into a real connection.','Bring the conversation and the next step together.','From a new prospect to a meeting on the calendar.']
];
const names = {daniel:['Daniel Carter','Head of Growth','Acme Corp'],olivia:['Olivia Vance','Growth Lead','Linear'],marcus:['Marcus Chen','Head of Sales','Figma'],sophia:['Sophia Martinez','Marketing Director','Vercel']};
const image=(id,size='')=>`<img class="avatar ${size}" src="${ASSETS[id]}" alt="" width="76" height="76">`;
const person=(id='daniel',large=false,logo=false)=>`<div class="person">${image(id,large?'large':'')}<div><h3>${names[id][0]}</h3><p class="muted">${names[id][1]}${large?'<br>Acme Corp':''}</p></div>${logo?'<span class="company-logo" aria-label="Acme Corp">A</span>':''}</div>`;
const svg='<svg class="wires" aria-hidden="true"></svg>';
const card=(id,tag)=>`<div class="ui-card source-card" id="source-${id}">${image(id,'small')}<div><h4>${names[id][0]}</h4><p class="muted">${names[id][1]}</p><span class="muted">${tag}</span></div><span class="company-logo">${id==='daniel'?'A':id==='olivia'?'◒':id==='marcus'?'F':'▲'}</span></div>`;
function sceneMarkup(i){
 if(i===0)return `<div class="scene discover-scene">${svg}<div class="source-list">${card('olivia','LinkedIn')}${card('daniel','Search match')}${card('marcus','Search match')}${card('sophia','Search match')}</div><div class="ui-card target-card" id="discover-target">${person('daniel',true,true)}<div class="contact-icons" aria-label="Email, LinkedIn and phone available"><span>✉</span><span><b>in</b></span><span>↗</span></div><div class="chip focus-tag">+ &nbsp;Discovered via Crunchbase</div><div class="chips"><span class="chip">120 employees</span><span class="chip">SaaS</span><span class="chip">SF Bay Area</span></div></div></div>`;
 if(i===1)return `<div class="scene research-scene">${svg}<div class="ui-card research-card" id="research-profile">${person('daniel',true)}<div class="details"><span>✉ &nbsp;daniel@acme.example</span><span>Location: &nbsp;San Francisco, CA</span><span>▧ &nbsp;120 employees · SaaS</span></div></div><div class="insights"><div class="section-label">Research insights</div>${[['↗','Recently raised a funding round','Series B · $18M · 3 weeks ago'],['≡','Expanding into new markets','EMEA & enterprise segments'],['◎','Hiring a growth team','3 open growth & performance roles'],['⌘','Uses HubSpot CRM','Active technology stack signal']].map((r,n)=>`<div class="insight-row" id="insight-${n}"><span class="insight-icon">${r[0]}</span><div><h4>${r[1]}</h4><p>${r[2]}</p></div></div>`).join('')}</div><aside class="ui-card sources-sidebar"><div class="section-label">Sources & context</div>${['Company website','LinkedIn Jobs','Funding announcement'].map(x=>`<div class="source-ref">↗ &nbsp;${x}<em>✓ Example source</em></div>`).join('')}</aside></div>`;
 if(i===2)return `<div class="scene qualify-scene">${svg}<div class="ui-card qualified-card" id="qualified-target"><div class="person">${image('daniel')}<div><h3>Daniel Carter</h3><p class="muted">Head of Growth · Acme Corp</p></div><span class="chip success verdict">✓ Qualified</span></div><div class="check-list">${[['Target industry','SaaS'],['Company size','50–200 · 120 employees'],['Relevant role','Growth · Head of Growth'],['Geography','US · San Francisco']].map(x=>`<div class="check-row"><span class="check">✓</span><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="score"><span class="score-ring"></span><div><strong>92 <span class="muted">/ 100</span></strong><div class="muted">Ideal customer fit</div></div></div></div><div class="ui-card rejected-card" id="rejected-target"><div class="person">${image('marcus','small')}<div><h4>Marcus Chen</h4><p class="muted">Head of Sales · Figma</p></div></div><div class="chip danger">× Not a fit</div><div class="details"><span>✓ &nbsp;Industry: SaaS</span><span style="color:var(--red)">× &nbsp;Company size: 200+</span><span style="color:var(--red)">× &nbsp;Role: Sales, not Growth</span></div></div></div>`;
 if(i===3)return `<div class="scene personalize-scene">${svg}<div class="ui-card context-card">${person('daniel')}<div class="section-label">Verified context events</div>${[['Recent funding round','Series B · $18M'],['Expanding into new markets','EMEA & enterprise focus'],['Hiring a growth team','3 open roles']].map((x,n)=>`<div class="context-event" id="context-${n}"><h4>${x[0]}</h4><p>${x[1]}</p></div>`).join('')}</div><div class="ui-card composer"><div class="composer-header"><span>To</span> Daniel Carter &lt;daniel@acme.example&gt;</div><div class="composer-header"><span>Subject</span> Your next chapter of growth</div><div class="email-body"><p class="email-line">Hi Daniel,</p><p class="email-line">Congrats on your <span class="phrase" id="phrase-0">recent funding round</span>. I noticed Acme Corp is <span class="phrase" id="phrase-1">expanding into new markets</span>.</p><p class="email-line">As your <span class="phrase" id="phrase-2">growth team scales</span>, we could help you start more relevant conversations with the right companies.</p><p class="email-line">Open to a quick chat this week?</p><p class="email-line">Best,<br>Tanim</p></div><div class="composer-footer"><span>+ Context-aware draft</span><span>3 connected signals</span></div></div></div>`;
 if(i===4)return `<div class="scene outreach-scene">${svg}<div class="outbound-list"><div class="section-label">Outbound queue</div><div class="ui-card draft-card" id="send-source">${person('daniel')}<div class="draft-preview"><b>Your next chapter of growth</b><br>Congrats on your recent funding round. I noticed Acme Corp is expanding into new markets…</div><div class="chips"><span class="chip success">✓ Qualified</span><span class="chip">Personalized</span></div></div>${['olivia','sophia'].map(id=>`<div class="ui-card queue-item">${image(id,'small')}<div><h4>${names[id][0]}</h4><div class="muted">Personalized draft</div></div><span class="chip">Queued</span></div>`).join('')}</div><div class="delivery" id="send-target"><div class="delivery-icon">↗</div><div class="section-label">Delivery status</div><span class="chip sent-badge">Sending</span><div class="muted">Personalized email</div></div></div>`;
 return `<div class="scene converse-scene"><div class="inbox"><div class="inbox-header"><span>Inbox &nbsp; › &nbsp; Daniel Carter</span><span>1 new reply</span></div><div class="inbox-content"><div class="reply-card"><div class="person">${image('daniel','small')}<h4>Daniel Carter</h4><span class="chip success verdict">Replied</span></div><div class="reply-copy"><p>Hi Tanim,</p><p>This looks interesting. We’re exploring ways to reach more of the right companies. Could we schedule a quick call to discuss?</p><p>Thanks,<br>Daniel</p></div></div><div class="meeting-card"><span class="chip success">▣ Meeting confirmed</span><h4>Acme Corp × Slidein</h4><p class="muted">Discovery conversation</p><div class="meeting-detail"><div class="calendar-tile"><span>OCT</span><b>22</b></div><p class="muted">Thursday, October 22<br>2:00–2:30 PM · New York</p></div><div class="attendees">${image('daniel','small')}<span class="attendee-t">T</span><span>Daniel & Tanim</span></div></div></div></div></div>`;
}
export function mountJourney(root, gsap, options={}) {
 if(!root || !gsap) throw new Error('mountJourney requires an element and GSAP.');
 const initial = Math.max(0,Math.min(5,Number(options.initialStage)||0));
 const abort=new AbortController(), media=window.matchMedia('(prefers-reduced-motion: reduce)');
 let current=initial, timeline=null, autoplay=false, timer=null, destroyed=false, resizeFrame=null, version=0;
 root.classList.add('sj');
 root.innerHTML=`<div class="sj-top"><div class="wordmark"><span class="brand-symbol" aria-hidden="true">↗</span>slidein<span style="color:var(--orange)">.</span></div><span class="demo-tag">The prospect journey</span></div><div class="sj-heading"><div><p class="eyebrow">From signal to conversation</p><h2></h2><p class="subtitle"></p></div><div class="step-counter"></div></div><div class="sj-nav" role="tablist" aria-label="Prospect journey stages">${stages.map((s,i)=>`<button type="button" class="step" id="sj-tab-${options.id||'demo'}-${i}" role="tab" data-step="${i}"><span>0${i+1}</span>${s[0]}</button>`).join('')}</div><div class="sj-viewport" role="tabpanel" id="sj-panel-${options.id||'demo'}" tabindex="0"></div><div class="sj-bottom"><div class="stage-caption"></div><button type="button" class="control replay" aria-label="Replay stage">Replay</button><button type="button" class="control auto" aria-pressed="false">▷ Play all</button><button type="button" class="control prev" aria-label="Previous stage">←</button><button type="button" class="control next">Next stage →</button></div><div class="demo-note">Interactive product demo. Fictional prospect data; no emails are sent and no meetings are booked.</div><div class="sr-only announcement" aria-live="polite"></div>`;
 const q=s=>root.querySelector(s),qa=s=>Array.from(root.querySelectorAll(s));
 const panel=q('.sj-viewport'); qa('.step').forEach(b=>b.setAttribute('aria-controls',panel.id));
 function updateAuto(){q('.auto').textContent=autoplay?'Ⅱ Pause':'▷ Play all';q('.auto').setAttribute('aria-pressed',String(autoplay));}
 function schedule(){clearTimeout(timer);if(autoplay&&!destroyed)timer=setTimeout(()=>{if(current===5){autoplay=false;updateAuto();}else show(current+1);},2200);}
 function stopAuto(){autoplay=false;clearTimeout(timer);updateAuto();}
 function links(){if(current===0)return ['olivia','daniel','marcus','sophia'].map(id=>[`#source-${id}`,'#discover-target']);if(current===1)return [0,1,2,3].map(n=>['#research-profile',`#insight-${n}`]);if(current===2)return [['#qualified-target','#rejected-target']];if(current===3)return [0,1,2].map(n=>[`#context-${n}`,`#phrase-${n}`]);if(current===4)return [['#send-source','#send-target']];return [];}
 function drawWires(){
  const scene=q('.scene'), layer=q('.wires');if(!layer)return;
  const r=scene.getBoundingClientRect(),mobile=window.matchMedia('(max-width:680px)').matches;
  layer.setAttribute('viewBox',`0 0 ${r.width} ${r.height}`); layer.innerHTML='';
  links().forEach(([a,b],n)=>{const x=q(a).getBoundingClientRect(),y=q(b).getBoundingClientRect();let sx,sy,ex,ey,d;
   if(mobile){sx=x.left-r.left+x.width/2;sy=x.bottom-r.top;ex=y.left-r.left+y.width/2;ey=y.top-r.top;const mid=(sy+ey)/2;d=`M${sx},${sy} C${sx},${mid} ${ex},${mid} ${ex},${ey}`;}
   else{sx=x.right-r.left;sy=x.top-r.top+x.height/2;ex=y.left-r.left;ey=y.top-r.top+y.height/2;if(current===0)ey+=(n-1.5)*10;const bend=Math.max(24,(ex-sx)*.5);d=`M${sx},${sy} C${sx+bend},${sy} ${ex-bend},${ey} ${ex},${ey}`;}
   if(mobile && current===0){const left=n%2===0,rail=left?-8:r.width+8;sx=(left?x.left:x.right)-r.left;sy=x.top-r.top+x.height/2;ex=y.left-r.left+y.width/2+(n-1.5)*8;ey=y.top-r.top;d=`M${sx},${sy} L${rail},${sy} L${rail},${ey-24} C${rail},${ey-8} ${ex},${ey-24} ${ex},${ey}`;}
   if(mobile && (current===1 || current===4)){const rail=-8;sx=x.left-r.left;sy=x.top-r.top+x.height/2;ex=y.left-r.left;ey=y.top-r.top+y.height/2;d=`M${sx},${sy} L${rail},${sy} L${rail},${ey} L${ex},${ey}`;}
   if(current===3){const composer=q('.composer').getBoundingClientRect();ey=y.bottom-r.top+2;ex=y.left-r.left;const rail=mobile?4+n*4:composer.left-r.left-12-n*7;if(mobile){sx=x.left-r.left;sy=x.top-r.top+x.height/2;}d=`M${sx},${sy} L${rail},${sy} L${rail},${ey} L${ex},${ey}`;}
   const ns='http://www.w3.org/2000/svg',p=document.createElementNS(ns,'path');p.setAttribute('d',d);p.setAttribute('class','wire');p.dataset.index=n;
   if(current===2){p.style.stroke='#aaa59b';p.style.opacity='.5';}
   layer.append(p);const dot=document.createElementNS(ns,'circle');dot.setAttribute('cx',sx);dot.setAttribute('cy',sy);dot.setAttribute('r','4');dot.setAttribute('class','wire-dot');layer.append(dot);
  });
  if(current===4){const p=document.createElementNS('http://www.w3.org/2000/svg','g');p.classList.add('plane-group');p.innerHTML='<path class="paper-plane" d="M-12,-9 L14,0 L-12,9 L-7,0 Z M-7,0 L14,0"/>';layer.append(p);}
 }
 function animate(){
  if(timeline)timeline.kill();drawWires();const versionNow=version;
  const tl=gsap.timeline({onComplete:()=>{if(versionNow===version)schedule();}}); timeline=tl;
  const paths=qa('.wire');paths.forEach(p=>{const len=p.getTotalLength();gsap.set(p,{strokeDasharray:len,strokeDashoffset:len});});
  tl.from(q('.scene'),{y:20,opacity:0,duration:.6,ease:'power2.out'},0);
  function wires(at,duration=.8){if(paths.length)tl.to(paths,{strokeDashoffset:0,duration,stagger:.09,ease:'power1.inOut'},at);}
  if(current===0){tl.from(qa('.source-card'),{x:-30,opacity:0,stagger:.13,duration:.5,ease:'power2.out'},.2);wires(.75);tl.from(q('.target-card'),{scale:.97,opacity:0,duration:.5},1.25).to(q('.target-card'),{boxShadow:'0 0 0 5px #ff620018',duration:.25,yoyo:true,repeat:1},1.8).from(q('.focus-tag'),{opacity:0,scale:.8,duration:.45,ease:'back.out(1.6)'},1.9);}
  if(current===1){wires(.45,.5);tl.from(qa('.insight-row'),{x:20,opacity:0,stagger:.15,duration:.5,ease:'power2.out'},.7).from(qa('.insight-icon'),{scale:.7,stagger:.15,duration:.35,ease:'back.out(2)'},.8).from(q('.sources-sidebar'),{opacity:0,duration:.7},1.15);}
  if(current===2){qa('.check').forEach((el,n)=>{const t=.55+n*.35;tl.to(el,{backgroundColor:'#2B8A3E',borderColor:'#2B8A3E',color:'#ffffff',duration:.15},t).fromTo(el,{scale:.8},{scale:1,duration:.15,ease:'back.out(2)'},t);});tl.to(q('.qualified-card'),{borderColor:'#2B8A3E',boxShadow:'0 0 0 2px #2b8a3e',duration:.3},2.05).from(q('.verdict'),{y:-12,opacity:0,duration:.4,ease:'back.out(1.6)'},2.05).from(q('.score'),{y:8,opacity:0,duration:.4},2.25);wires(2.5);tl.from(q('.rejected-card'),{opacity:0,y:12,duration:.5},2.8);}
  if(current===3){tl.from(q('.composer'),{x:20,opacity:0,duration:.5},.2).from(qa('.context-event'),{x:-12,opacity:0,stagger:.15,duration:.4},.2);qa('.email-line').forEach(el=>{const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const f=document.createDocumentFragment();node.textContent.split(/(\s+)/).forEach(word=>{if(!word.trim())f.append(document.createTextNode(word));else{const s=document.createElement('span');s.className='email-word';s.textContent=word;f.append(s);}});node.replaceWith(f);});});tl.from(qa('.email-word'),{opacity:0,stagger:.035,duration:.15,ease:'none'},.65);paths.forEach((p,n)=>{tl.to(p,{strokeDashoffset:0,duration:.65,ease:'power1.inOut'},1.3+n*.65).fromTo(q(`#phrase-${n}`),{backgroundColor:'transparent',color:'#272522'},{backgroundColor:'#fff2e8',color:'#b34200',duration:.4},1.3+n*.65);});}
  if(current===4){tl.from(qa('.queue-item'),{y:12,opacity:0,stagger:.12,duration:.4},.3);wires(.55);const plane=q('.plane-group'), route=paths[0],proxy={t:0};const move=()=>{const len=route.getTotalLength(),v=route.getPointAtLength(proxy.t*len),a=route.getPointAtLength(Math.max(0,proxy.t*len-1)),b=route.getPointAtLength(Math.min(len,proxy.t*len+1));plane.setAttribute('transform',`translate(${v.x},${v.y}) rotate(${Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI})`);};move();tl.from(plane,{opacity:0,duration:.1},.9).to(proxy,{t:1,duration:1.5,ease:'power2.inOut',onUpdate:move},.9).to(plane,{opacity:0,duration:.15},2.35).call(()=>{q('.sent-badge').textContent='✓ Sent';},[],2.45).to(q('.sent-badge'),{backgroundColor:'#e9f4eb',color:'#2b8a3e',borderColor:'#2b8a3e55',duration:.2},2.45).fromTo(q('.sent-badge'),{scale:1.15},{scale:1,duration:.4,ease:'back.out(2)'},2.45).to(q('.delivery-icon'),{backgroundColor:'#e9f4eb',color:'#2b8a3e',duration:.3},2.45);}
  if(current===5){tl.from(q('.reply-card'),{x:-20,opacity:0,duration:.6},.3).from(q('.reply-card .verdict'),{scale:.8,opacity:0,duration:.4,ease:'back.out(1.5)'},.75).from(q('.meeting-card'),{y:30,opacity:0,duration:.6,ease:'back.out(1.4)'},1.3);}
  if(media.matches)tl.progress(1);
 }
 function show(i){clearTimeout(timer);version++;if(timeline)timeline.kill();current=i;const s=stages[i];q('h2').textContent=s[1];q('.subtitle').textContent=s[2];q('.step-counter').innerHTML=`<b>0${i+1}</b> / 06`;q('.stage-caption').textContent=s[3];qa('.step').forEach((el,n)=>{el.setAttribute('aria-selected',String(n===i));el.tabIndex=n===i?0:-1;});panel.setAttribute('aria-labelledby',qa('.step')[i].id);q('.prev').disabled=i===0;q('.next').textContent=i===5?'Start again':'Next stage →';panel.innerHTML=sceneMarkup(i);q('.announcement').textContent=`Stage ${i+1} of 6: ${s[0]}`;animate();}
 root.addEventListener('click',e=>{const button=e.target.closest('button');if(!button||!root.contains(button))return;if(button.dataset.step!==undefined){stopAuto();show(Number(button.dataset.step));}else if(button.matches('.next')){stopAuto();show((current+1)%6);}else if(button.matches('.prev')){stopAuto();show(Math.max(0,current-1));}else if(button.matches('.replay')){clearTimeout(timer);show(current);}else if(button.matches('.auto')){autoplay=!autoplay;updateAuto();if(autoplay){if(current===5)show(0);else show(current);}else clearTimeout(timer);}}, {signal:abort.signal});
 q('.sj-nav').addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?5:(current+(e.key==='ArrowRight'?1:5))%6;stopAuto();show(n);qa('.step')[n].focus();},{signal:abort.signal});
 let previousWidth=root.getBoundingClientRect().width-2;const observer=new ResizeObserver(entries=>{const width=entries[0].contentRect.width;if(Math.abs(width-previousWidth)<1)return;previousWidth=width;if(resizeFrame)cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{if(destroyed)return;if(timeline)timeline.progress(1);drawWires();qa('.wire').forEach(p=>gsap.set(p,{strokeDashoffset:0}));const plane=q('.plane-group');if(plane)gsap.set(plane,{opacity:0});});});
 const preferenceChange=()=>{if(media.matches){stopAuto();timeline?.progress(1);}};media.addEventListener('change',preferenceChange);
 show(initial);observer.observe(root);
 const api={goTo(i){stopAuto();show(Math.max(0,Math.min(5,i)));},get stage(){return current;},finish(){timeline?.progress(1);},destroy(){destroyed=true;clearTimeout(timer);if(resizeFrame)cancelAnimationFrame(resizeFrame);timeline?.kill();observer.disconnect();media.removeEventListener('change',preferenceChange);abort.abort();root.innerHTML='';root.classList.remove('sj');delete root.journey;}};root.journey=api;return api;
}
